import os
import boto3

def fetch_profile_claims(access_token: str) -> dict:
    """
    Fetches and normalizes federated user profile claims using AWS Cognito.
    """
    cognito_region = os.environ.get("AWS_REGION")

    if not cognito_region:
        raise ValueError("Missing required environment variable: AWS_REGION")

    client = boto3.client('cognito-idp', region_name=cognito_region)

    try:
        user_info = client.get_user(
            AccessToken=access_token
        )

        # Normalize claims
        normalized_claims = {
            "username": user_info.get("Username"),
            "attributes": {},
            "provider": "AWS_Cognito"
        }

        for attr in user_info.get("UserAttributes", []):
            normalized_claims["attributes"][attr["Name"]] = attr["Value"]

        return normalized_claims
    except client.exceptions.UserNotFoundException:
        return {"error": "User not found or invalid access token."}
    except Exception as e:
        return {"error": str(e)}

import os
import boto3

def translate_consent_copy(text: str, source_language_code: str, target_language_code: str) -> dict:
    """
    Translates identity-provider consent copy using AWS Translate.
    """
    translate = boto3.client('translate', region_name=os.environ.get("AWS_REGION"))

    try:
        response = translate.translate_text(
            Text=text,
            SourceLanguageCode=source_language_code,
            TargetLanguageCode=target_language_code
        )
        translated_text = response.get('TranslatedText')

        return {
            "original_text": text,
            "source_language": source_language_code,
            "target_language": target_language_code,
            "translated_text": translated_text
        }
    except Exception as e:
        return {"error": str(e)}

import os
import boto3
from datetime import datetime
import uuid

def persist_audit_record(event_data: dict, table_name: str) -> dict:
    """
    Persists federated-login audit records in an AWS DynamoDB managed document store.
    """
    dynamodb = boto3.resource('dynamodb', region_name=os.environ.get("AWS_REGION"))
    table = dynamodb.Table(table_name)

    try:
        audit_record = {
            'auditId': str(uuid.uuid4()),
            'timestamp': datetime.utcnow().isoformat(),
            'eventType': event_data.get("eventType", "FederatedLoginEvent"),
            'userId': event_data.get("userId"),
            'provider': event_data.get("provider"),
            'details': event_data  # Store all event data as details
        }

        table.put_item(Item=audit_record)

        return {
            "message": "Audit record persisted successfully.",
            "auditId": audit_record['auditId']
        }
    except Exception as e:
        return {"error": str(e)}
